  [inst : MeasurableSpace Ω] {α : ι → Type u_13} [n : (i : ι) → MeasurableSpace (α i)] {f : (i : ι) → Ω → α i}
  {μ : Measure Ω} (i : ι) [inst_1 : Inv (α i)] [inst_2 : MeasurableInv (α i)] [inst_3 : DecidableEq ι]
  (h : iIndepFun n f μ) (j : ι) (hj : ¬j = i) : Measurable (update (fun x => id) i (fun x => x⁻¹) j) := by
  simp [hj]

