theorem ProbabilityTheory.iIndepFun.extracted_1.{u_10, u_9, u_8, u_2} {Ω : Type u_2} [inst : MeasurableSpace Ω]
  {μ : Measure Ω} {ι : Type u_8} {ι' : Type u_9} {α : ι → Type u_10} {n : (i : ι) → MeasurableSpace (α i)}
  {f : (i : ι) → Ω → α i} {hf : ∀ (i : ι), Measurable (f i)} {ST : ι' → Finset ι} (hS : Pairwise (Disjoint on ST))
  (h : iIndepFun n f μ) :
  let g := (fun {x} => Subtype.val) ∘' Sigma.snd;
  Injective g →
    let β := fun k => (i : { x // x ∈ ST k }) → α ↑i;
    iIndepFun (fun x => MeasurableSpace.pi) (fun k x i => f (↑i) x) μ := by
  let m (i : ι') (j : ST i) : MeasurableSpace (α j) := n j
    exact iIndepFun.pi' (m := m) (hf ∘' g) (h.reindex_of_injective g hg)

protected theorem MeasurableSet.univ_pi [Countable δ] {t : ∀ i : δ, Set (π i)}
    (ht : ∀ i, MeasurableSet (t i)) : MeasurableSet (pi univ t) :=
  MeasurableSet.pi (to_countable _) fun i _ => ht i

